// Port of Aml.Engine.Resources.AMLStandard.AMLLibraries (Aml.Engine.Resources 4.2.1), the access
// to the AutomationML standard libraries that are embedded in that assembly. The resources are
// embedded here as TS modules (src/engine/resources/libraries/data, generated by
// scripts/gen-aml-libraries.mjs). A .NET Stream is represented by the resource bytes.
// The assembly also embeds the library catalog Aml.Engine.Resources.Resources.AutomationMLLibs.json,
// which no code of Aml.Engine.Resources reads (GetAutomationMLLibrary only builds names of *.aml
// resources, ReadAutomationMLLibraryInformation reads a catalog file); getManifestResourceStream
// serves it, and every other resource, by its manifest resource name.

import { T } from '../../registry.js';
import { ArgumentException, ArgumentNullException, DirectoryNotFoundException, FileNotFoundException } from '../../../system/exceptions.js';
import { isNullOrEmpty } from '../../../system/strings.js';
import { directoryExists, fileExists, getDirectoryName, getFs, getFullPath } from '../../amlobjects/internal/NetPath.js';
import { EMBEDDED_LIBRARIES } from './data/index.js';
import { embeddedLibraryBytes } from './EmbeddedLibrary.js';
import type { PublicLibraryCatalog } from '../catalogue/PublicLibraryCatalog.js';

/** Name of the assembly that embeds the libraries (`assembly.GetName().Name`). */
const ASSEMBLY_NAME = 'Aml.Engine.Resources';

/** Provides access to AML Library resources. */
export class AMLLibraries {
  private constructor() {}

  /**
   * Gets the AutomationMLBaseAttributeTypeLib for the specified CAEX version and AML version.
   * @deprecated Use generic version GetAutomationMLLibrary
   */
  static automationMLBaseAttributeTypeLib(AMLversion: string | null, CAEXVersion: string | null): Uint8Array | null {
    return AMLLibraries.getAutomationMLLibrary('AutomationMLBaseAttributeTypeLib', AMLversion, CAEXVersion);
  }

  /**
   * Gets the AutomationMLBaseRoleClassLib for the specified CAEX version and AML version.
   * @deprecated Use generic version GetAutomationMLLibrary
   */
  static automationMLBaseRoleClassLib(AMLversion: string | null, CAEXVersion: string | null): Uint8Array | null {
    return AMLLibraries.getAutomationMLLibrary('AutomationMLBaseRoleClassLib', AMLversion, CAEXVersion);
  }

  /**
   * Gets the AutomationMLBPRInterfaceClassLib for the specified CAEX version and AML version.
   * @deprecated Use generic version GetAutomationMLLibrary
   */
  static automationMLBPRInterfaceClassLib(AMLversion: string | null, CAEXVersion: string | null): Uint8Array | null {
    return AMLLibraries.getAutomationMLLibrary('AutomationMLBPRInterfaceClassLib', AMLversion, CAEXVersion);
  }

  /**
   * Gets the AutomationMLBPRRoleClassLib for the specified CAEX version and AML version.
   * @deprecated Use generic version GetAutomationMLLibrary
   */
  static automationMLBPRRoleClassLib(AMLversion: string | null, CAEXVersion: string | null): Uint8Array | null {
    return AMLLibraries.getAutomationMLLibrary('AutomationMLBPRRoleClassLib', AMLversion, CAEXVersion);
  }

  /**
   * Gets the AutomationMLInterfaceClassLib for the specified CAEX version and AML version.
   * @deprecated Use generic version GetAutomationMLLibrary
   */
  static automationMLInterfaceClassLib(AMLversion: string | null, CAEXVersion: string | null): Uint8Array | null {
    return AMLLibraries.getAutomationMLLibrary('AutomationMLInterfaceClassLib', AMLversion, CAEXVersion);
  }

  /**
   * Gets the AutomationML library with the specified name for the specified CAEX version
   * ('CAEX2_15', 'CAEX3_0', also '2.15', '3.0') and AML version ('AML2_0', 'AML2_10', also '2.0',
   * '2.1', '2.10'). Only the embedded libraries are available.
   * @returns The bytes of the library document (the embedded resource stream), or `null` when no
   * such resource is embedded or a version is not valid.
   */
  static getAutomationMLLibrary(libraryName: string, AMLversion: string | null, CAEXVersion: string | null): Uint8Array | null {
    const text = AMLLibraries.fullResourceName(AMLversion, CAEXVersion, libraryName + '.aml');
    if (text != null) {
      return AMLLibraries.getManifestResourceStream(text);
    }
    return null;
  }

  /**
   * `typeof(AMLLibraries).Assembly.GetManifestResourceStream(name)` (port helper, no C# member):
   * the bytes of the embedded resource with this manifest resource name (case-sensitive), e.g.
   * `Aml.Engine.Resources.Resources.AutomationMLLibs.json`, or `null` when there is none. A null
   * or empty name throws like RuntimeAssembly.GetManifestResourceStream.
   */
  static getManifestResourceStream(name: string): Uint8Array | null {
    if (name === null || name === undefined) throw new ArgumentNullException(null, 'String reference not set to an instance of a String.');
    if (name.length === 0) throw new ArgumentException('String cannot have zero length.');
    const library = EMBEDDED_LIBRARIES.get(name);
    return library === undefined ? null : embeddedLibraryBytes(library);
  }

  /**
   * @internal Reads the AutomationML library information containing all AutomationML published
   * Library names. A `catalogFile` has to be provided. The current Catalog can be obtained from
   * AutomationML. File.OpenRead and JsonSerializer.Deserialize<PublicLibraryCatalog>(stream) with
   * the default options (Node only).
   * @returns The AutomationML library catalog.
   */
  static readAutomationMLLibraryInformation(catalogFile: string | null): PublicLibraryCatalog | null {
    if (isNullOrEmpty(catalogFile)) {
      throw new ArgumentNullException('catalogFile');
    }
    // File.OpenRead: FileNotFoundException with the full path for a missing file,
    // DirectoryNotFoundException when its directory is missing.
    const fs = getFs();
    if (!fileExists(catalogFile)) {
      const fullPath = getFullPath(catalogFile);
      if (!directoryExists(getDirectoryName(fullPath))) {
        throw new DirectoryNotFoundException(`Could not find a part of the path '${fullPath}'.`);
      }
      throw new FileNotFoundException(`Could not find file '${fullPath}'.`);
    }
    const stream = fs.readFileSync(catalogFile);
    if (stream != null) {
      return T.PublicLibraryCatalog.deserialize(stream);
    }
    return null;
  }

  /** Gets the full resource name for the given resource. */
  private static fullResourceName(AMLversion: string | null, CAEXVersion: string | null, resource: string): string | null {
    const caex = AMLLibraries.isValidCAEXVersion(CAEXVersion);
    if (!caex.result) return null;
    // C# evaluates IsValidAMLVersion only when the CAEX version is valid; a null AML version
    // throws there (NullReferenceException in .NET, TypeError here).
    const aml = AMLLibraries.isValidAMLVersion(AMLversion as string);
    if (!aml.result) return null;
    let amlFolder = aml.amlFolder;
    if (amlFolder === 'AML2_1') {
      amlFolder = 'AML2_10';
    }
    return `${ASSEMBLY_NAME}.Resources.${caex.caexFolder}.${amlFolder}.${resource}`;
  }

  /** Determines whether the specified AML version is valid. */
  private static isValidAMLVersion(amlVersion: string): { result: boolean; amlFolder: string } {
    let amlFolder = amlVersion;
    if (!amlFolder.startsWith('AML')) {
      amlFolder = 'AML' + amlFolder;
    }
    amlFolder = amlFolder.replaceAll('.', '_');
    switch (amlFolder) {
      case 'AML2_0':
      case 'AML2_10':
      case 'AML2_1':
        return { result: true, amlFolder };
      default:
        return { result: false, amlFolder };
    }
  }

  /** Checks if this is a valid CAEX version string. */
  private static isValidCAEXVersion(schemaVersion: string | null): { result: boolean; caexFolder: string | null } {
    let caexFolder = schemaVersion;
    if (schemaVersion == null || schemaVersion.length === 0) {
      return { result: false, caexFolder };
    }
    if (!schemaVersion.startsWith('CAEX')) {
      caexFolder = 'CAEX' + schemaVersion;
    }
    caexFolder = caexFolder!.replaceAll('.', '_');
    const text = caexFolder;
    if (text === 'CAEX2_15' || text === 'CAEX3_0') {
      return { result: true, caexFolder };
    }
    return { result: false, caexFolder };
  }
}
